def parse_pair(txt):
    def grab(label):
        m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)', txt)
        h,w=int(m.group(1)),int(m.group(2))
        rows=[[int(x) for x in r.split()] for r in m.group(3).strip().split('\n')]
        a=np.array(rows)
        assert a.shape==(h,w), (a.shape,h,w)
        return a
    return grab('input'), grab('output')
